// Biologie Klasse 5–7 – weitere Themen (Themenübersicht orientiert an "Erlebnis Bio NRW" Band 1; eigene Texte, eigene Bilder)
kap('bio5-08', { e: '🌱🐾🧬', titel: 'Kennzeichen der Lebewesen', bt: 'Was macht etwas lebendig?',
  ein: '<p>Wie erkennt man, ob etwas lebt? Ein Hund lebt, ein Stein nicht. Alle Lebewesen haben gemeinsame <b>Kennzeichen</b>: Sie nehmen Stoffe auf und geben welche ab, sie wachsen, sie bewegen sich, sie reagieren auf ihre Umwelt und sie pflanzen sich fort.</p><p>Auch Pflanzen bewegen sich, nur langsam: Sie wachsen zum Licht.</p>',
  m: 'Lebewesen haben Stoffwechsel, Wachstum und Entwicklung, Bewegung, Reizbarkeit, Fortpflanzung und bestehen aus Zellen.',
  aus: '<h3>Die sieben Kennzeichen</h3><ul><li><b>Stoffwechsel:</b> Nahrung aufnehmen, verwerten, Abfälle abgeben.</li><li><b>Wachstum und Entwicklung:</b> vom Baby zum Erwachsenen, vom Samen zur Pflanze.</li><li><b>Fortpflanzung:</b> Nachkommen bekommen.</li><li><b>Reizbarkeit:</b> auf Licht, Wärme, Berührung oder Geräusche reagieren.</li><li><b>Bewegung:</b> Tiere laufen, Pflanzen wachsen zum Licht.</li><li><b>Zellen:</b> alle Lebewesen bestehen aus Zellen.</li><li><b>Tod:</b> jedes Lebewesen lebt nur eine bestimmte Zeit.</li></ul><h3>Prüfe es!</h3><p>Ein Feuer wächst und braucht Sauerstoff, ist aber kein Lebewesen: Es hat keine Zellen und keinen Stoffwechsel. Ein Auto bewegt sich, wächst aber nicht und pflanzt sich nicht fort.</p>',
  f: [['🍽️', 'Stoffwechsel', 'Lebewesen nehmen Stoffe auf, bauen sie um und geben Abfälle ab.'], ['👶', 'Wachstum', 'Lebewesen wachsen und entwickeln sich.'], ['👀', 'Reizbarkeit', 'Sie reagieren auf Reize wie Licht, Wärme und Berührung.']],
  u: [['Was gehört zu den Kennzeichen der Lebewesen?', 'Fortpflanzung', 'Eine feste Form', 'Ein Motor', 'Keine Veränderung', 'Nur Lebewesen können sich fortpflanzen.'], ['Warum ist ein Feuer kein Lebewesen?', 'Es hat keine Zellen und keinen Stoffwechsel', 'Es ist zu heiß', 'Es leuchtet', 'Es bewegt sich nicht', 'Zellen und Stoffwechsel fehlen.'], ['Bewegen sich Pflanzen?', 'Ja, langsam, zum Beispiel zum Licht hin', 'Nein, nie', 'Nur Bäume', 'Nur im Winter', 'Sie wachsen und drehen sich zum Licht.'], ['Woraus bestehen alle Lebewesen?', 'Aus Zellen', 'Aus Metall', 'Aus Stein', 'Aus Luft', 'Zellen sind die Bausteine des Lebens.']] });

kap('bio5-09', { e: '🐺➡️🐕', titel: 'Vom Wolf zum Hund', bt: 'Der Hund stammt vom Wolf ab.',
  ein: '<p>Vor vielen tausend Jahren haben sich Wölfe den Menschen genähert und fraßen ihre Reste. Die Menschen zähmten und züchteten sie. So entstanden die <b>Hunde</b>. Heute gibt es über 300 Hunderassen.</p><p>Hunde sind noch wie Wölfe: Sie leben gern in der Gruppe, bellen, knurren und zeigen Körpersprache.</p>',
  m: 'Haustiere stammen von Wildtieren ab. Durch Zucht entstanden aus dem Wolf viele Hunderassen.',
  aus: '<h3>Domestikation</h3><p>Domestikation heißt, ein Wildtier zum Haustier zu machen. Beim Hund geschah das vor mindestens 15 000 Jahren. Die Forschung streitet noch über das genaue Alter.</p><h3>Wolf und Hund im Vergleich</h3><table><tr><th></th><th>Wolf</th><th>Hund</th></tr><tr><td>Leben</td><td>im Rudel mit Rangordnung</td><td>in der Familie, Mensch als Partner</td></tr><tr><td>Aussehen</td><td>einheitlich</td><td>sehr unterschiedlich (Dackel bis Dogge)</td></tr><tr><td>Verhalten</td><td>scheu</td><td>zutraulich</td></tr></table><h3>Zucht</h3><p>Züchter wählen Tiere mit gewünschten Eigenschaften aus (Jagdhund, Hütehund, Schoßhund). Übertriebene Zucht kann krank machen, zum Beispiel Atemprobleme bei sehr kurzen Nasen.</p><h3>Verantwortung</h3><p>Ein Hund braucht Auslauf, Futter, Erziehung und Zeit – über 10 bis 15 Jahre.</p>',
  f: [['🐺', 'Der Vorfahre', 'Der Wolf ist der wilde Vorfahre unserer Hunde.'], ['✂️', 'Zucht', 'Auswählen und Verpaaren führt zu verschiedenen Rassen.'], ['❤️', 'Verantwortung', 'Hunde brauchen Zeit, Bewegung und liebevolle Erziehung.']],
  u: [['Von welchem Wildtier stammt der Hund ab?', 'Vom Wolf', 'Vom Fuchs', 'Vom Bären', 'Vom Luchs', 'Der Wolf ist der Vorfahre.'], ['Was bedeutet Domestikation?', 'Ein Wildtier zum Haustier machen', 'Ein Tier jagen', 'Ein Tier fangen und essen', 'Ein Tier im Zoo halten', 'Menschen zähmen und züchten die Tiere.'], ['Wie nennt man das Auswählen der Tiere für gewünschte Eigenschaften?', 'Zucht', 'Jagd', 'Zähmung', 'Wanderung', 'Dadurch entstehen Rassen.'], ['Was braucht ein Hund?', 'Auslauf, Futter und Zuwendung', 'Nur Wasser', 'Nur Spielzeug', 'Keine Zeit', 'Er ist ein soziales Tier.']] });

kap('bio5-10', { e: '🐱🐾👁️', titel: 'Katzen sind Schleichjäger', bt: 'Die Katze ist perfekt zum Anschleichen gebaut.',
  ein: '<p>Katzen jagen allein und schleichen sich an ihre Beute an. Dafür haben sie <b>Samtpfoten</b> mit einziehbaren Krallen, <b>Schnurrhaare</b> zum Tasten und Augen, die auch bei wenig Licht gut sehen.</p><p>Beim Sprung packt die Katze die Beute mit Krallen und Zähnen.</p>',
  m: 'Katzen sind Schleichjäger: weiche Pfoten, einziehbare Krallen, Tasthaare, Nachtsicht und ein Raubtiergebiss.',
  aus: '<h3>Angepasst an die Jagd</h3><ul><li><b>Pfoten:</b> weiche Ballen, die Schritte sind fast lautlos. Die Krallen sind einziehbar und bleiben scharf.</li><li><b>Augen:</b> Die Pupille wird bei Licht zu einem Schlitz und im Dunkeln groß. Eine spiegelnde Schicht im Auge verstärkt das Licht.</li><li><b>Ohren:</b> beweglich, hören sehr hohe Töne (z. B. Mäuse).</li><li><b>Schnurrhaare:</b> Tasthaare, mit denen sie Engen und Bewegungen spüren.</li><li><b>Gebiss:</b> spitze Eckzähne zum Töten, Reißzähne zum Zerteilen von Fleisch.</li></ul><h3>Körper</h3><p>Der Körper ist biegsam und kräftig. Katzen landen meist auf den Pfoten, weil sie sich in der Luft drehen können.</p><h3>Mensch und Katze</h3><p>Hauskatzen stammen von der Falbkatze (Wildkatze Nordafrikas) ab. Sie jagen auch, wenn sie satt sind – das ist ein Instinkt.</p>',
  f: [['🐾', 'Leise Pfoten', 'Weiche Ballen und einziehbare Krallen.'], ['👁️', 'Nachtsicht', 'Die Pupille weitet sich und spiegelnde Zellen verstärken das Licht.'], ['🦷', 'Raubtiergebiss', 'Spitze Eckzähne und scharfe Reißzähne.']],
  u: [['Wozu sind die Krallen der Katze einziehbar?', 'Sie bleiben scharf und die Pfoten leise', 'Damit sie schneller läuft', 'Damit sie schwimmen kann', 'Damit sie besser riecht', 'So nutzen sich die Krallen nicht ab.'], ['Wozu dienen die Schnurrhaare?', 'Zum Tasten', 'Zum Riechen', 'Zum Hören', 'Zum Schwimmen', 'Sie sind Tasthaare.'], ['Was ist eine Katze?', 'Ein Einzeljäger und Schleichjäger', 'Ein Hetzjäger im Rudel', 'Ein Pflanzenfresser', 'Ein Allesfresser', 'Katzen schleichen und springen.'], ['Welche Zähne zerteilen Fleisch?', 'Reißzähne', 'Schneidezähne', 'Milchzähne', 'Weisheitszähne', 'Sie wirken wie eine Schere.']] });

kap('bio5-11', { e: '🐄🥛🌾', titel: 'Rinder sind Nutztiere', bt: 'Kühe geben Milch und sind Wiederkäuer.',
  ein: '<p>Rinder liefern <b>Milch</b>, <b>Fleisch</b> und Leder. Sie fressen Gras und Heu. Weil Gras schwer verdaulich ist, <b>kauen Kühe wieder</b>: Sie würgen das Futter hoch und kauen es noch einmal.</p><p>Deshalb nennt man sie <b>Wiederkäuer</b>. Sie haben vier Mägen.</p>',
  m: 'Rinder sind Wiederkäuer mit vier Mägen. Sie liefern Milch und Fleisch.',
  aus: '<h3>Die vier Mägen</h3><ol><li><b>Pansen:</b> riesiger Gärraum, in dem Mikroben das Gras aufschließen.</li><li><b>Netzmagen:</b> formt kleine Ballen zum Hochwürgen.</li><li><b>Blättermagen:</b> entzieht Wasser und zerreibt.</li><li><b>Labmagen:</b> eigentlicher Magen mit Verdauungssäften.</li></ol><h3>Gebiss</h3><p>Rinder haben unten Schneidezähne, oben eine Hornplatte. Mit den breiten Backenzähnen mahlen sie das Gras.</p><h3>Milch</h3><p>Eine Kuh gibt Milch, nachdem sie ein Kalb geboren hat. Eine Milchkuh gibt am Tag etwa 25 bis 30 Liter. Aus der Milch macht man Butter, Käse, Joghurt und Quark.</p><h3>Tierhaltung</h3><p>Weide, Offenstall und Biohaltung geben den Tieren mehr Platz. Wer Fleisch und Milch kauft, entscheidet mit, wie Tiere gehalten werden.</p>',
  f: [['🔁', 'Wiederkäuer', 'Futter wird hochgewürgt und noch einmal gekaut.'], ['🫘', 'Vier Mägen', 'Pansen, Netzmagen, Blättermagen, Labmagen.'], ['🥛', 'Milch', 'Aus der Milch entstehen Käse, Butter, Joghurt und mehr.']],
  u: [['Wie viele Mägen hat ein Rind?', 'Vier', 'Einen', 'Zwei', 'Sechs', 'Das gilt für alle Wiederkäuer.'], ['Wie heißt der größte Magen?', 'Pansen', 'Labmagen', 'Blättermagen', 'Netzmagen', 'Im Pansen wird das Gras aufgeschlossen.'], ['Warum kaut eine Kuh wieder?', 'Gras ist schwer verdaulich', 'Sie hat Langeweile', 'Sie hat Zahnschmerzen', 'Sie hat Durst', 'Das zweite Kauen zerkleinert die Fasern.'], ['Was entsteht aus Milch?', 'Käse und Butter', 'Mehl', 'Zucker', 'Öl', 'Das sind Milchprodukte.']] });

kap('bio6-12', { e: '🌬️🐾💧', titel: 'Wie sich Pflanzen verbreiten', bt: 'Samen reisen mit Wind, Wasser und Tieren.',
  ein: '<p>Eine Pflanze kann nicht laufen. Damit ihre Samen einen guten Platz finden, nutzen sie Helfer: den <b>Wind</b> (Löwenzahn), das <b>Wasser</b> (Kokosnuss), <b>Tiere</b> (Kletten) und die eigene <b>Schleuderkraft</b> (Springkraut).</p>',
  m: 'Samen und Früchte haben passende Einrichtungen zur Verbreitung: Flügel, Schirmchen, Haken, Schwimmkörper oder Lockfarben.',
  aus: '<h3>Verbreitung durch Wind</h3><p>Löwenzahn hat Schirmchen, Ahorn hat Flügel, Mohn schüttelt winzige Samen aus Kapseln.</p><h3>Verbreitung durch Wasser</h3><p>Kokosnüsse und Erlenfrüchte schwimmen.</p><h3>Verbreitung durch Tiere</h3><ul><li><b>Klettfrüchte</b> (Klette) bleiben im Fell hängen.</li><li><b>Fleischige Früchte</b> (Kirsche, Beeren) werden gefressen. Die Samen werden ausgeschieden.</li><li><b>Nüsse</b> werden von Eichhörnchen und Eichelhähern versteckt und manchmal vergessen.</li></ul><h3>Selbstverbreiter</h3><p>Die Früchte des Springkrauts platzen bei Berührung auf und schleudern die Samen weg.</p><h3>Warum ist das wichtig?</h3><p>So gibt es keinen Streit um Licht und Platz mit der Mutterpflanze, und neue Gebiete werden besiedelt.</p>',
  f: [['🌬️', 'Wind', 'Schirmchen und Flügel tragen Samen weit.'], ['🐕', 'Tiere', 'Kletten im Fell, Beeren im Magen: Tiere bringen Samen weg.'], ['💥', 'Selbst', 'Springkraut schleudert seine Samen weg.']],
  u: [['Wie verbreitet sich der Löwenzahn?', 'Mit dem Wind', 'Mit dem Wasser', 'Mit Tieren im Fell', 'Mit Schleuderkraft', 'Seine Schirmchen fliegen.'], ['Wie verbreitet sich die Klette?', 'Im Fell von Tieren', 'Mit dem Wind', 'Im Wasser', 'Von selbst', 'Ihre Haken hängen sich fest.'], ['Wie verbreitet sich das Springkraut?', 'Es schleudert die Samen', 'Es schwimmt', 'Es fliegt', 'Es kriecht', 'Die Früchte platzen auf.'], ['Warum ist Verbreitung nützlich?', 'Die Pflanze erobert neue Plätze', 'Die Pflanze wird größer', 'Die Pflanze wird schneller', 'Die Pflanze verliert Blätter', 'Sie hat weniger Konkurrenz.']] });

kap('bio6-13', { e: '🥔🌿🟤', titel: 'Die Kartoffel', bt: 'Die Knolle speichert Stärke.',
  ein: '<p>Die Kartoffel ist eine <b>Sprossknolle</b>. Unter der Erde wachsen an Ausläufern dicke Knollen. Sie speichern <b>Stärke</b> für die Pflanze. Wir essen diese Knollen.</p><p>Die grünen Teile der Pflanze und grüne Stellen an der Knolle sind giftig!</p>',
  m: 'Die Kartoffel speichert Stärke in Knollen und kann sich daraus ungeschlechtlich vermehren.',
  aus: '<h3>Heimat und Geschichte</h3><p>Die Kartoffel stammt aus den Anden in Südamerika und kam im 16. Jahrhundert nach Europa. Heute ist sie ein Grundnahrungsmittel.</p><h3>Bau</h3><ul><li><b>Knolle:</b> verdickter Spross mit „Augen“, aus denen neue Triebe wachsen.</li><li><b>Kraut:</b> die grünen Blätter machen Fotosynthese.</li><li><b>Blüten und Beeren:</b> giftig (Solanin).</li></ul><h3>Vermehrung</h3><p>Aus einer Knolle mit Auge wächst eine neue Pflanze. Das ist <b>ungeschlechtliche Vermehrung</b>, die neuen Pflanzen sind Klone der Mutterpflanze.</p><h3>Nährstoffe</h3><p>Kartoffeln enthalten viel Stärke, außerdem Vitamin C, Kalium und Ballaststoffe. Sie haben wenig Fett – Pommes und Chips dagegen viel.</p><h3>Nachweis von Stärke</h3><p>Ein Tropfen Iod-Lösung färbt Stärke blauschwarz.</p>',
  f: [['🌱', 'Knolle', 'Die Knolle ist ein verdickter Spross und speichert Stärke.'], ['☠️', 'Giftig', 'Grünes Kraut, Beeren und grüne Stellen enthalten Solanin.'], ['🧪', 'Stärketest', 'Iod färbt Stärke blauschwarz.']],
  u: [['Was speichert die Kartoffelknolle?', 'Stärke', 'Eiweiß', 'Fett', 'Wasser nur', 'Stärke ist ein Energievorrat.'], ['Woher stammt die Kartoffel?', 'Aus Südamerika', 'Aus Asien', 'Aus Afrika', 'Aus Europa', 'Sie kam im 16. Jahrhundert zu uns.'], ['Was ist an der Kartoffelpflanze giftig?', 'Kraut und Beeren', 'Die gekochte Knolle', 'Die Wurzel nur', 'Nichts', 'Sie enthalten Solanin.'], ['Wie nennt man Vermehrung aus einer Knolle?', 'Ungeschlechtliche Vermehrung', 'Bestäubung', 'Befruchtung', 'Samenverbreitung', 'Es sind genetisch gleiche Klone.']] });

kap('bio6-14', { e: '🌾🍞🌽', titel: 'Getreide und Mehl', bt: 'Vom Korn zum Brot.',
  ein: '<p>Getreide sind Gräser, deren Körner wir essen. Dazu gehören <b>Weizen, Roggen, Gerste, Hafer, Mais und Reis</b>. Die Körner sitzen in einer <b>Ähre</b> (bei Mais im Kolben).</p><p>Aus den Körnern wird Mehl gemahlen. Aus Mehl backen wir Brot, Brötchen und Nudeln.</p>',
  m: 'Getreide liefert Stärke und ist ein wichtiges Grundnahrungsmittel. Mehlkörper, Schale und Keimling sind die Teile des Korns.',
  aus: '<h3>Das Getreidekorn</h3><ul><li><b>Schale (Kleie):</b> Ballaststoffe, Mineralstoffe.</li><li><b>Mehlkörper:</b> viel Stärke, daraus wird helles Mehl.</li><li><b>Keimling:</b> Vitamine und Fett, aus ihm wächst eine neue Pflanze.</li></ul><h3>Vollkorn oder Weißmehl?</h3><p>Vollkornmehl enthält alle Teile. Weißmehl besteht nur aus dem Mehlkörper. Vollkorn macht länger satt.</p><h3>Von der Saat zum Brot</h3><ol><li>Aussaat, Wachstum, Ernte mit dem Mähdrescher.</li><li>Mahlen in der Mühle.</li><li>Teig kneten, Hefe lässt ihn gehen, backen.</li></ol><h3>Wichtige Getreidearten</h3><table><tr><th>Getreide</th><th>Verwendung</th></tr><tr><td>Weizen</td><td>Brot, Brötchen, Nudeln</td></tr><tr><td>Roggen</td><td>dunkles Brot</td></tr><tr><td>Hafer</td><td>Haferflocken</td></tr><tr><td>Mais</td><td>Futter, Popcorn</td></tr><tr><td>Reis</td><td>Hauptnahrung in Asien</td></tr></table>',
  f: [['🌾', 'Die Ähre', 'In der Ähre sitzen die Getreidekörner.'], ['🔬', 'Das Korn', 'Schale, Mehlkörper und Keimling.'], ['🍞', 'Brot', 'Mehl, Wasser, Hefe: Der Teig geht auf und wird gebacken.']],
  u: [['Was ist Getreide?', 'Gräser mit essbaren Körnern', 'Wurzelgemüse', 'Früchte von Bäumen', 'Pilze', 'Weizen, Roggen und Mais sind Gräser.'], ['Welcher Teil des Korns liefert helles Mehl?', 'Der Mehlkörper', 'Die Schale', 'Der Keimling', 'Das Stroh', 'Er besteht fast nur aus Stärke.'], ['Was macht den Brotteig locker?', 'Hefe', 'Salz', 'Mehl', 'Wasser', 'Hefe bildet Kohlenstoffdioxid.'], ['Welches Getreide wächst in Asien oft im Wasserfeld?', 'Reis', 'Roggen', 'Hafer', 'Gerste', 'Reis wächst auf Nassfeldern.']] });

kap('bio6-15', { e: '🌼🗝️📖', titel: 'Pflanzen ordnen und bestimmen', bt: 'Mit dem Bestimmungsschlüssel findest du jede Pflanze.',
  ein: '<p>Es gibt über 300 000 Pflanzenarten. Damit man sie nicht verwechselt, <b>ordnet</b> man sie nach Merkmalen: Blattform, Blütenfarbe, Zahl der Blütenblätter.</p><p>Mit einem <b>Bestimmungsschlüssel</b> beantwortest du Fragen mit „ja“ oder „nein“ und kommst so zum Namen der Pflanze. Gepresste Pflanzen klebt man in ein <b>Herbarium</b>.</p>',
  m: 'Bestimmungsschlüssel führen durch Ja-Nein-Fragen zum Namen. Ein Herbarium sammelt gepresste Pflanzen.',
  aus: '<h3>Bestimmen</h3><p>Du beobachtest genau (mit Lupe) und gehst im Schlüssel Schritt für Schritt vor. Beispiel: „Blätter ganzrandig oder gezähnt?“ – „Blüte mit vier Blütenblättern?“ So grenzt man die Auswahl ein.</p><h3>Pflanzenfamilien</h3><ul><li><b>Korbblütler:</b> Löwenzahn, Gänseblümchen (viele kleine Blüten in einem Körbchen).</li><li><b>Rosengewächse:</b> Wildrose, Apfel, Erdbeere.</li><li><b>Kreuzblütler:</b> Raps, Senf (vier Blütenblätter in Kreuzform).</li><li><b>Schmetterlingsblütler:</b> Erbse, Klee.</li></ul><h3>Herbarium anlegen</h3><ol><li>Nur häufige Pflanzen pflücken, geschützte nie!</li><li>Zwischen Zeitungspapier unter Büchern pressen und trocknen.</li><li>Auf Papier kleben und beschriften (Name, Fundort, Datum).</li></ol>',
  f: [['🗝️', 'Schlüssel', 'Ja-Nein-Fragen führen zum Namen.'], ['🌸', 'Familien', 'Pflanzen mit ähnlichem Bau gehören zu einer Familie.'], ['📖', 'Herbarium', 'Pressen, trocknen, aufkleben, beschriften.']],
  u: [['Was ist ein Bestimmungsschlüssel?', 'Eine Fragenfolge, die zum Namen führt', 'Ein Schloss', 'Ein Pflanzenbuch ohne Bilder', 'Ein Gartenwerkzeug', 'Er arbeitet mit Merkmalen.'], ['Welche Pflanze ist ein Korbblütler?', 'Löwenzahn', 'Raps', 'Erbse', 'Apfel', 'Viele Röhrenblüten bilden ein Körbchen.'], ['Was gehört auf ein Herbarium-Blatt?', 'Name, Fundort und Datum', 'Nur das Foto', 'Nur das Gewicht', 'Nur der Preis', 'So bleibt der Fund nachvollziehbar.'], ['Welche Pflanzen darf man nie pflücken?', 'Geschützte Arten', 'Löwenzahn', 'Gänseblümchen', 'Gras', 'Sie stehen unter Naturschutz.']] });

kap('bio6-16', { e: '🌱🍃🌸', titel: 'Pflanzenorgane und ihre Funktion', bt: 'Wurzel, Spross, Blatt und Blüte haben jeweils eine Aufgabe.',
  ein: '<p>Eine Pflanze besteht aus Teilen mit besonderen Aufgaben: Die <b>Wurzel</b> hält sie fest und nimmt Wasser auf. Der <b>Spross</b> (Stängel) trägt die Blätter und leitet das Wasser. Das <b>Blatt</b> macht Zucker mit Licht. Die <b>Blüte</b> dient der Fortpflanzung.</p><p>Nur wenn alle Teile zusammenarbeiten, lebt die Pflanze – sie sind ein <b>System</b>.</p>',
  m: 'Jedes Pflanzenorgan hat eine Funktion: Wurzel – Aufnahme, Spross – Stütze und Leitung, Blatt – Fotosynthese, Blüte – Fortpflanzung.',
  aus: '<h3>Die Organe im Überblick</h3><table><tr><th>Organ</th><th>Aufgabe</th></tr><tr><td>Wurzel</td><td>Verankern, Wasser und Mineralstoffe aufnehmen, manchmal Stoffe speichern (Möhre)</td></tr><tr><td>Spross</td><td>Stützen, Wasser nach oben und Zucker nach unten leiten</td></tr><tr><td>Blatt</td><td>Fotosynthese, Wasserdampf abgeben (Verdunstung)</td></tr><tr><td>Blüte</td><td>Bestäubung, Früchte und Samen bilden</td></tr></table><h3>Struktur und Funktion</h3><p>Der Bau passt zur Aufgabe: Blätter sind flach und fangen viel Licht. Wurzeln verzweigen sich fein, um viel Boden zu erreichen. Der Spross ist stabil und hat Leitungsbahnen wie Röhren.</p><h3>Experiment</h3><p>Stelle eine weiße Blume in Wasser mit Tinte. Nach einigen Stunden sind die Blätter gefärbt: Das Wasser wurde durch den Spross geleitet.</p>',
  f: [['🌱', 'Wurzel', 'Verankert die Pflanze und nimmt Wasser auf.'], ['🍃', 'Blatt', 'Hier findet die Fotosynthese statt.'], ['🧩', 'System', 'Alle Organe arbeiten zusammen.']],
  u: [['Welche Aufgabe hat die Wurzel?', 'Verankern und Wasser aufnehmen', 'Fotosynthese', 'Samen bilden', 'Bestäuben', 'Sie sitzt im Boden.'], ['Wo findet die Fotosynthese statt?', 'Im Blatt', 'In der Wurzel', 'In der Blüte', 'Im Samen', 'Das Blattgrün fängt das Licht.'], ['Wozu dient die Blüte?', 'Zur Fortpflanzung', 'Zum Atmen', 'Zum Festhalten', 'Zum Trinken', 'Aus ihr werden Früchte.'], ['Wie leitet die Pflanze Wasser?', 'Durch den Spross', 'Durch die Blüte', 'Durch die Frucht', 'Gar nicht', 'Röhren im Spross leiten das Wasser.']] });

kap('bio6-17', { e: '🌳🐦🐿️', titel: 'Der Baum als Lebensraum', bt: 'In und auf einem Baum wohnen viele Tiere.',
  ein: '<p>Ein alter Baum ist wie ein Hochhaus mit vielen Wohnungen. In der <b>Krone</b> brüten Vögel, am <b>Stamm</b> klettern Käfer und Spechte, in der <b>Rinde</b> verstecken sich Insekten und unter dem Baum leben Würmer und Asseln.</p><p>Sogar toter Baum ist Lebensraum.</p>',
  m: 'Ein Baum bietet Nahrung, Wohnung und Schutz in vielen „Stockwerken“. Totholz ist besonders wertvoll.',
  aus: '<h3>Stockwerke</h3><ul><li><b>Krone:</b> Vögel, Eichhörnchen, Raupen, Blattläuse.</li><li><b>Stamm und Rinde:</b> Käfer, Spinnen, Ameisen, Moose und Flechten, Specht.</li><li><b>Baumhöhlen:</b> Meisen, Spechte, Fledermäuse, Siebenschläfer.</li><li><b>Boden und Wurzeln:</b> Regenwürmer, Asseln, Pilze, Mäuse.</li></ul><h3>Totholz</h3><p>Abgestorbene Äste und Stämme sind Nahrung und Wohnung für Hunderte Arten, zum Beispiel für Hirschkäferlarven.</p><h3>Was der Baum für uns tut</h3><p>Er macht Sauerstoff, spendet Schatten, kühlt die Luft und bindet Kohlenstoffdioxid.</p><h3>Beispiel Eiche</h3><p>Auf einer alten Eiche leben mehrere hundert Insektenarten.</p>',
  f: [['🌲', 'Stockwerke', 'Krone, Stamm, Rinde und Boden haben verschiedene Bewohner.'], ['🪵', 'Totholz', 'Totes Holz ist Lebensraum für viele Käfer und Pilze.'], ['🌍', 'Nutzen', 'Bäume liefern Sauerstoff, Schatten und Lebensraum.']],
  u: [['Wo brüten viele Vögel auf dem Baum?', 'In der Krone', 'Im Boden', 'In der Wurzel', 'Im Stamminneren immer', 'Dort sind sie sicher.'], ['Wer wohnt in Baumhöhlen?', 'Meisen und Fledermäuse', 'Regenwürmer', 'Fische', 'Kühe', 'Höhlen bieten Schutz.'], ['Warum ist Totholz wertvoll?', 'Es ist Lebensraum und Nahrung', 'Es ist wertlos', 'Es vergiftet den Boden', 'Es verbraucht Sauerstoff', 'Viele Käfer und Pilze leben darin.'], ['Was erzeugt ein Baum für uns?', 'Sauerstoff', 'Plastik', 'Strom', 'Benzin', 'Bei der Fotosynthese entsteht Sauerstoff.']] });

kap('bio6-18', { e: '🌿🦔🍒', titel: 'Die Hecke als Lebensraum', bt: 'Hecken sind Schutz, Futter und Nest zugleich.',
  ein: '<p>Eine <b>Hecke</b> besteht aus Sträuchern wie Schlehe, Weißdorn, Hasel und Wildrose. Sie bietet Tieren Nahrung (Beeren, Insekten), Nistplätze und Verstecke.</p><p>Igel, Zaunkönig, Mäuse und viele Schmetterlinge leben in Hecken. Hecken bremsen den Wind und schützen den Boden.</p>',
  m: 'Hecken sind artenreiche Lebensräume und verbinden Biotope miteinander.',
  aus: '<h3>Aufbau einer Hecke</h3><ul><li><b>Mantel:</b> Außenrand mit Sträuchern.</li><li><b>Kern:</b> dichte Mitte, geschützte Nistplätze.</li><li><b>Saum:</b> Krautstreifen davor mit Blumen und Gräsern.</li></ul><h3>Bewohner</h3><table><tr><th>Tier</th><th>Nutzt die Hecke als …</th></tr><tr><td>Zaunkönig, Amsel</td><td>Nistplatz</td></tr><tr><td>Igel</td><td>Versteck und Winterquartier</td></tr><tr><td>Schmetterlinge, Bienen</td><td>Nektarquelle</td></tr><tr><td>Marienkäfer</td><td>Überwinterung</td></tr></table><h3>Nutzen</h3><p>Windschutz, Schutz vor Bodenabtrag, Nahrung für Tiere und Menschen (Holunder, Schlehe). Hecken verbinden Wald und Feld und helfen Tieren zu wandern.</p><h3>Schutz</h3><p>Das Heckenschneiden ist zwischen März und September verboten, damit Vögel in Ruhe brüten.</p>',
  f: [['🌿', 'Aufbau', 'Mantel, Kern und Saum bilden die Hecke.'], ['🦔', 'Bewohner', 'Igel, Vögel, Insekten: viele Arten teilen sich die Hecke.'], ['🌬️', 'Windschutz', 'Hecken bremsen Wind und schützen den Boden.']],
  u: [['Welche Pflanze gehört in eine Hecke?', 'Schlehe', 'Kaktus', 'Palme', 'Reis', 'Schlehe, Weißdorn und Wildrose wachsen in Hecken.'], ['Wie nutzt der Igel die Hecke?', 'Als Versteck und Winterquartier', 'Als Schwimmbad', 'Gar nicht', 'Nur als Weg', 'Dort findet er auch Insekten.'], ['Warum darf man im Sommer keine Hecke schneiden?', 'Vögel brüten dort', 'Sie wächst sonst nicht', 'Sie ist giftig', 'Sie ist zu nass', 'Das schützt Nester.'], ['Was macht eine Hecke für den Boden?', 'Sie schützt vor Wind und Abtragung', 'Sie macht ihn trocken', 'Sie vergiftet ihn', 'Sie macht ihn flach', 'Die Wurzeln halten den Boden fest.']] });

kap('bio6-19', { e: '🐌🪱🦑', titel: 'Wirbellose Tiere', bt: 'Mehr als 95 von 100 Tierarten haben keine Wirbelsäule.',
  ein: '<p><b>Wirbellose</b> sind Tiere ohne Wirbelsäule. Dazu gehören Schnecken, Würmer, Muscheln, Krebse, Insekten und Spinnen. Die allermeisten Tierarten sind wirbellos.</p><p>Die Weinbergschnecke trägt ihr Haus auf dem Rücken und bewegt sich mit einem Muskelfuß.</p>',
  m: 'Wirbellose haben keine Wirbelsäule. Sie bilden die größte Gruppe im Tierreich.',
  aus: '<h3>Wichtige Gruppen</h3><table><tr><th>Gruppe</th><th>Beispiele</th><th>Merkmal</th></tr><tr><td>Weichtiere</td><td>Schnecke, Muschel, Tintenfisch</td><td>weicher Körper, oft Schale</td></tr><tr><td>Ringelwürmer</td><td>Regenwurm, Blutegel</td><td>Körper in Ringe gegliedert</td></tr><tr><td>Gliederfüßer</td><td>Insekten, Spinnen, Krebse</td><td>Außenskelett, gegliederte Beine</td></tr><tr><td>Nesseltiere</td><td>Quallen, Korallen</td><td>Nesselzellen</td></tr><tr><td>Stachelhäuter</td><td>Seestern, Seeigel</td><td>Stacheln, fünfstrahlig</td></tr></table><h3>Die Weinbergschnecke</h3><p>Sie hat ein Gehäuse zum Schutz, zwei Fühlerpaare und eine Raspelzunge (Radula). Sie zieht sich bei Trockenheit zurück und verschließt das Haus.</p><h3>Wichtig im Naturhaushalt</h3><p>Wirbellose bestäuben, zersetzen und dienen vielen anderen Tieren als Futter.</p>',
  f: [['🐌', 'Weichtiere', 'Schnecken und Muscheln haben weiche Körper, oft mit Schale.'], ['🪱', 'Ringelwürmer', 'Der Körper besteht aus vielen Ringen.'], ['🦀', 'Gliederfüßer', 'Insekten, Spinnen und Krebse haben ein Außenskelett.']],
  u: [['Was haben Wirbellose nicht?', 'Eine Wirbelsäule', 'Ein Herz', 'Einen Körper', 'Nahrung', 'Das sagt schon ihr Name.'], ['Zu welcher Gruppe gehört die Schnecke?', 'Weichtiere', 'Ringelwürmer', 'Nesseltiere', 'Wirbeltiere', 'Muscheln gehören auch dazu.'], ['Welche Tiere haben ein Außenskelett?', 'Gliederfüßer', 'Schnecken', 'Quallen', 'Seesterne', 'Insekten, Spinnen und Krebse.'], ['Wie viel Prozent der Tierarten sind wirbellos?', 'Über 95 Prozent', 'Etwa 5 Prozent', 'Genau 50 Prozent', 'Etwa 20 Prozent', 'Wirbeltiere sind nur eine kleine Gruppe.']] });

kap('bio6-20', { e: '🐞🐛🥬', titel: 'Nützlinge und Schädlinge', bt: 'Der Marienkäfer frisst Blattläuse.',
  ein: '<p>Tiere, die uns helfen, nennt man <b>Nützlinge</b>, zum Beispiel Marienkäfer, Igel und Bienen. Tiere, die Ernten fressen, nennt man <b>Schädlinge</b>, zum Beispiel Blattläuse.</p><p>In der Natur ist aber kein Tier „gut“ oder „böse“. Jedes hat seine Rolle im Netz des Lebens.</p>',
  m: 'Nützlinge halten Schädlinge in Grenzen. Natürliche Feinde ersetzen oft Gift.',
  aus: '<h3>Beispiele</h3><table><tr><th>Nützling</th><th>Hilft durch …</th></tr><tr><td>Marienkäfer</td><td>frisst Blattläuse</td></tr><tr><td>Schlupfwespe</td><td>legt Eier in Schädlingsraupen</td></tr><tr><td>Igel</td><td>frisst Schnecken und Larven</td></tr><tr><td>Biene</td><td>bestäubt Blüten</td></tr><tr><td>Regenwurm</td><td>lockert den Boden</td></tr></table><p>Schädlinge: Blattläuse (saugen Pflanzensaft), Kartoffelkäfer, Kohlweißlings-Raupen, Nacktschnecken im Salat.</p><h3>Biologische Schädlingsbekämpfung</h3><p>Man setzt natürliche Feinde ein, zum Beispiel Marienkäfer im Gewächshaus. Das schont die Umwelt. Gift tötet auch Nützlinge und Bienen.</p><h3>Garten</h3><p>Wildblumen, Hecken, Steinhaufen und Insektenhotels holen Nützlinge in den Garten.</p>',
  f: [['🐞', 'Nützling', 'Marienkäfer und Igel helfen bei der Schädlingsbekämpfung.'], ['🐛', 'Schädling', 'Blattläuse und Raupen fressen an Nutzpflanzen.'], ['🌼', 'Naturnah', 'Ein vielfältiger Garten lockt Nützlinge an.']],
  u: [['Was frisst der Marienkäfer?', 'Blattläuse', 'Blüten', 'Nektar', 'Gras', 'Er ist ein Nützling.'], ['Warum ist Gift problematisch?', 'Es tötet auch Nützlinge', 'Es hilft nur Nützlingen', 'Es lässt Pflanzen wachsen', 'Es macht Wasser sauber', 'Auch Bienen sterben daran.'], ['Was ist biologische Schädlingsbekämpfung?', 'Einsatz natürlicher Feinde', 'Einsatz von Gift', 'Ernte früher', 'Mehr Dünger', 'Es nutzt die Natur selbst.'], ['Welches Tier ist in der Natur „gut“ oder „böse“?', 'Keines, jedes hat eine Rolle', 'Nur Käfer sind böse', 'Nur Vögel sind gut', 'Nur Säugetiere sind gut', 'Nützling und Schädling hängen vom Standpunkt des Menschen ab.']] });

kap('bio6-21', { e: '🦔😴❄️', titel: 'Säugetiere im Winter', bt: 'Winterschlaf, Winterruhe oder aktiv bleiben.',
  ein: '<p>Im Winter gibt es wenig Futter und es ist kalt. Säugetiere haben drei Wege: Manche halten <b>Winterschlaf</b> (Igel, Siebenschläfer), manche <b>Winterruhe</b> (Eichhörnchen, Dachs) und manche sind <b>aktiv</b> (Reh, Fuchs, Hase).</p>',
  m: 'Winterschläfer senken Körpertemperatur und Herzschlag stark. Winterruher wachen oft auf. Winteraktive bekommen ein dichtes Winterfell.',
  aus: '<h3>Winterschlaf</h3><p>Der Igel senkt seine Körpertemperatur von etwa 35 °C auf etwa 5 °C. Das Herz schlägt nur noch wenige Male pro Minute. Er lebt von seinem Fettvorrat und braucht vorher Gewicht, mindestens etwa 500 Gramm.</p><h3>Winterruhe</h3><p>Eichhörnchen und Dachse schlafen viel, aber ihre Körpertemperatur sinkt kaum. Sie wachen auf, fressen von Vorräten und schlafen weiter.</p><h3>Winteraktiv</h3><p>Rehe, Füchse, Hasen und Wildschweine haben im Winter ein dichteres, oft dunkleres Fell. Sie fressen Rinde, Knospen und Reste.</p><h3>Fledermäuse</h3><p>Sie halten in Höhlen und Kellern Winterschlaf. Störungen kosten sie wertvolle Energie.</p><h3>Hilfe für Igel</h3><p>Laubhaufen im Garten lassen und Wasser anbieten. Kranke, untergewichtige Igel gehören zur Pflegestation.</p>',
  f: [['😴', 'Winterschlaf', 'Körpertemperatur und Herzschlag sinken stark.'], ['🌰', 'Winterruhe', 'Tiere schlafen viel, wachen aber auf und fressen.'], ['🦌', 'Aktiv', 'Reh und Fuchs bleiben wach und haben ein Winterfell.']],
  u: [['Welches Tier hält Winterschlaf?', 'Igel', 'Reh', 'Fuchs', 'Hase', 'Er senkt seine Körpertemperatur stark.'], ['Was machen Eichhörnchen im Winter?', 'Winterruhe mit Fressphasen', 'Winterschlaf wie der Igel', 'Sie ziehen nach Afrika', 'Sie sind das ganze Jahr wach und aktiv', 'Sie wachen zum Fressen auf.'], ['Was lässt Igel im Winter überleben?', 'Ein Fettvorrat', 'Ein Schneeanzug', 'Zucker im Blut', 'Warme Höhlen aus Metall', 'Sie fressen sich vorher Fett an.'], ['Welche Tiere sind im Winter aktiv?', 'Reh und Fuchs', 'Igel und Siebenschläfer', 'Fledermaus und Murmeltier', 'Frosch und Eidechse', 'Sie haben ein dichtes Winterfell.']] });

kap('bio6-22', { e: '🕊️🏳️✈️', titel: 'Zugvögel und Standvögel', bt: 'Manche Vögel fliegen im Herbst nach Süden.',
  ein: '<p><b>Zugvögel</b> wie Storch, Schwalbe und Kuckuck fliegen im Herbst in den warmen Süden, weil sie bei uns im Winter nichts zu fressen finden. <b>Standvögel</b> wie Amsel, Meise und Spatz bleiben das ganze Jahr hier.</p><p>Manche Vögel sind <b>Teilzieher</b>: Ein Teil bleibt, ein Teil zieht.</p>',
  m: 'Zugvögel weichen dem Nahrungsmangel aus. Sie orientieren sich an Sonne, Sternen und dem Magnetfeld der Erde.',
  aus: '<h3>Warum ziehen Vögel?</h3><p>Insektenfresser finden im Winter keine Insekten. Deshalb ziehen Schwalben, Kuckuck und Mauersegler fort. Körnerfresser wie Spatzen finden dagegen weiter Samen.</p><h3>Wie finden sie den Weg?</h3><ul><li>Stand der Sonne und der Sterne</li><li>Magnetfeld der Erde</li><li>Landmarken wie Küsten und Flüsse</li><li>Erfahrung und angeborenes Wissen</li></ul><h3>Strecken</h3><p>Rauchschwalben fliegen bis nach Südafrika, etwa 10 000 Kilometer. Störche aus Westeuropa fliegen meist nach Spanien oder Westafrika.</p><h3>Teilzieher</h3><p>Rotkehlchen und Star ziehen zum Teil.</p><h3>Winterfütterung</h3><p>Standvögel kann man mit Sonnenblumenkernen oder Meisenknödeln unterstützen. Sauberkeit am Futterhaus ist wichtig.</p>',
  f: [['🧭', 'Orientierung', 'Sonne, Sterne und Magnetfeld zeigen den Weg.'], ['🏠', 'Standvögel', 'Amsel, Meise und Spatz bleiben bei uns.'], ['🌻', 'Futterhaus', 'Im Winter kann man Standvögel mit Körnern füttern.']],
  u: [['Welcher Vogel ist ein Zugvogel?', 'Die Rauchschwalbe', 'Die Amsel', 'Der Spatz', 'Die Blaumeise', 'Sie überwintert in Afrika.'], ['Warum ziehen Insektenfresser fort?', 'Im Winter gibt es keine Insekten', 'Es ist zu hell', 'Sie langweilen sich', 'Sie lieben Wärme nur', 'Es fehlt ihnen das Futter.'], ['Wonach orientieren sich Zugvögel?', 'Sonne, Sterne und Magnetfeld', 'Nur nach Straßen', 'Nach dem Wind allein', 'Nach Wolken', 'Mehrere Orientierungshilfen gleichzeitig.'], ['Was sind Standvögel?', 'Vögel, die das ganze Jahr bleiben', 'Vögel ohne Flügel', 'Vögel, die nur stehen', 'Vögel im Zoo', 'Zum Beispiel Amsel und Spatz.']] });

kap('bio6-23', { e: '🐸🌡️🥶', titel: 'Wechselwarme Tiere im Winter', bt: 'Kältestarre: Frosch und Eidechse schlafen im Versteck.',
  ein: '<p>Frösche, Eidechsen und Insekten sind <b>wechselwarm</b>: Ihre Körpertemperatur ist so hoch wie die Umgebung. Im Winter werden sie steif und bewegen sich nicht. Man nennt das <b>Kältestarre</b>.</p><p>Sie verstecken sich dafür im Boden, im Laubhaufen oder im Teichschlamm.</p>',
  m: 'Wechselwarme Tiere haben keine eigene konstante Körpertemperatur. Im Winter verfallen sie in Kältestarre.',
  aus: '<h3>Wechselwarm und gleichwarm</h3><table><tr><th></th><th>Wechselwarm</th><th>Gleichwarm</th></tr><tr><td>Beispiele</td><td>Fische, Frösche, Eidechsen, Insekten</td><td>Vögel, Säugetiere</td></tr><tr><td>Körpertemperatur</td><td>folgt der Umgebung</td><td>immer etwa gleich (Mensch 37 °C)</td></tr><tr><td>Energiebedarf</td><td>niedrig</td><td>hoch</td></tr></table><h3>Überwinterung</h3><ul><li><b>Frösche:</b> im Teichschlamm oder unter Laub.</li><li><b>Eidechsen:</b> in Erdlöchern.</li><li><b>Insekten:</b> als Ei, Larve oder Puppe, manche als Käfer in Rindenspalten, Marienkäfer oft in Gruppen.</li></ul><h3>Warum geht das?</h3><p>In der Starre verbrauchen die Tiere fast keine Energie. Atmung und Herzschlag sind sehr langsam. Ihr Fettvorrat reicht bis zum Frühling.</p><h3>Wichtig</h3><p>Laubhaufen und Totholz im Garten lassen helfen den Tieren beim Überwintern.</p>',
  f: [['🌡️', 'Wechselwarm', 'Die Körpertemperatur folgt der Umgebungstemperatur.'], ['🥶', 'Kältestarre', 'Im Winter bewegen sich die Tiere nicht und sparen Energie.'], ['🍂', 'Verstecke', 'Laub, Teichschlamm und Erde schützen vor Frost.']],
  u: [['Welches Tier ist wechselwarm?', 'Der Frosch', 'Der Hund', 'Die Meise', 'Das Reh', 'Auch Eidechsen und Fische sind wechselwarm.'], ['Was ist Kältestarre?', 'Ein Zustand mit fast keiner Bewegung bei Kälte', 'Ein Wintersport', 'Ein Winterfell', 'Ein Vogelzug', 'Das Tier spart so Energie.'], ['Wo überwintern Frösche?', 'Im Teichschlamm oder unter Laub', 'Im Baumwipfel', 'In der Luft', 'In Nestern', 'Dort ist es frostfrei.'], ['Welche Tiere sind gleichwarm?', 'Vögel und Säugetiere', 'Fische', 'Frösche', 'Eidechsen', 'Sie halten ihre Körpertemperatur konstant.']] });

kap('bio6-24', { e: '🦇🔊🌙', titel: 'Fledermäuse', bt: 'Fledermäuse jagen mit Ultraschall in der Nacht.',
  ein: '<p>Fledermäuse sind <b>Säugetiere</b>, die fliegen können. Ihre Flügel bestehen aus einer dünnen Flughaut, die zwischen den langen Fingern gespannt ist. Sie jagen nachts Insekten.</p><p>Dabei rufen sie Töne, die wir nicht hören (<b>Ultraschall</b>). Das Echo zeigt ihnen, wo die Beute ist.</p>',
  m: 'Fledermäuse sind fliegende Säugetiere. Sie orientieren sich per Echoortung und halten Winterschlaf.',
  aus: '<h3>Echoortung</h3><p>Die Fledermaus sendet Ultraschallrufe aus. Treffen sie auf ein Hindernis oder Insekt, kommen sie als Echo zurück. Aus der Zeit bis zum Echo berechnet das Gehirn die Entfernung.</p><h3>Bau</h3><ul><li>Flughaut zwischen Fingern, Körper und Beinen.</li><li>Haarpelz, Säugezitzen: Das Junge wird gesäugt.</li><li>Tagsüber hängt sie mit dem Kopf nach unten in Höhlen, Dachböden oder Baumhöhlen.</li></ul><h3>Lebensweise</h3><p>Eine Zwergfledermaus frisst pro Nacht bis zu 3000 Mücken. Im Winter halten Fledermäuse Winterschlaf in Höhlen und Kellern.</p><h3>Schutz</h3><p>Alle heimischen Fledermäuse sind streng geschützt. Sie leiden unter Insektensterben, Verlust von Quartieren und Licht in der Nacht.</p>',
  f: [['🔊', 'Echoortung', 'Ultraschall-Echos zeigen Hindernisse und Beute.'], ['🧬', 'Säugetier', 'Fledermäuse haben Fell und säugen ihre Jungen.'], ['🛡️', 'Schutz', 'Alle Arten sind in Deutschland geschützt.']],
  u: [['Was sind Fledermäuse?', 'Säugetiere', 'Vögel', 'Insekten', 'Reptilien', 'Sie haben Fell und säugen die Jungen.'], ['Wie finden sie Beute im Dunkeln?', 'Mit Ultraschall-Echoortung', 'Mit Licht', 'Mit dem Geruch allein', 'Mit Tasthaaren', 'Das Echo gibt ihnen ein Bild.'], ['Wo schlafen sie im Winter?', 'In Höhlen und Kellern', 'Im Baumwipfel', 'In der Wüste', 'Auf Wiesen', 'Dort ist es kühl, aber frostfrei.'], ['Was frisst eine heimische Fledermaus?', 'Insekten', 'Blut', 'Früchte allein', 'Fische', 'Zum Beispiel Mücken und Nachtfalter.']] });

kap('bio6-25', { e: '🐪🐧🏔️', titel: 'Leben in extremen Lebensräumen', bt: 'Wüste, Polarregion und Hochgebirge fordern Anpassungen.',
  ein: '<p>Manche Lebensräume sind besonders hart: Hitze und Trockenheit in der <b>Wüste</b>, Eis und Kälte in den <b>Polarregionen</b> oder dünne Luft im <b>Hochgebirge</b>. Tiere dort haben besondere <b>Angepasstheiten</b>.</p><p>Das Kamel kommt lange ohne Wasser aus, der Pinguin hält sich mit einer dicken Fettschicht warm.</p>',
  m: 'Angepasstheiten helfen Tieren in extremen Lebensräumen zu überleben.',
  aus: '<h3>Wüste</h3><ul><li><b>Kamel:</b> Fett im Höcker als Energiespeicher, breite Füße gegen das Einsinken, lange Wimpern gegen Sand.</li><li><b>Wüstenfuchs (Fennek):</b> große Ohren geben Körperwärme ab, nachtaktiv.</li></ul><h3>Polarregion</h3><ul><li><b>Eisbär:</b> dichtes Fell, dicke Fettschicht, weißes Fell als Tarnung.</li><li><b>Pinguin:</b> dichte Federn, Fettschicht, Zusammenrücken in der Gruppe.</li></ul><h3>Hochgebirge</h3><ul><li><b>Steinbock, Gämse:</b> sichere Klettertiere mit harten Hufen.</li><li><b>Murmeltier:</b> hält Winterschlaf.</li></ul><h3>Regel von Bergmann</h3><p>Verwandte Tiere sind in kalten Regionen oft größer, weil große Tiere im Verhältnis weniger Wärme verlieren.</p><h3>Gefahr</h3><p>Der Klimawandel bedroht Eisbären, weil das Meereis schmilzt.</p>',
  f: [['🐪', 'Wüste', 'Wasser sparen und Hitze aushalten.'], ['🐧', 'Polar', 'Fett und dichtes Gefieder gegen Kälte.'], ['🏔️', 'Gebirge', 'Sicher klettern und mit dünner Luft leben.']],
  u: [['Was speichert das Kamel im Höcker?', 'Fett', 'Wasser', 'Luft', 'Sand', 'Das Fett liefert Energie.'], ['Wozu hat der Fennek große Ohren?', 'Zur Wärmeabgabe', 'Zum Schwimmen', 'Zum Graben', 'Zum Wasser trinken', 'So kühlt er sich.'], ['Was schützt Pinguine vor der Kälte?', 'Federn und Fettschicht', 'Ein dichtes Fell', 'Eine Panzerschicht', 'Warme Haut', 'Dazu rücken sie eng zusammen.'], ['Was bedroht Eisbären besonders?', 'Das Schmelzen des Meereises', 'Zu viel Schnee', 'Zu viele Pinguine', 'Zu wenig Sonne', 'Sie brauchen das Eis zur Jagd.']] });

kap('bio7-11', { e: '🦷🪥😁', titel: 'Zähne und Zahnpflege', bt: 'Gesunde Zähne brauchen Pflege.',
  ein: '<p>Kinder haben 20 <b>Milchzähne</b>. Sie fallen zwischen etwa 6 und 12 Jahren aus. Danach wachsen 28 bis 32 <b>bleibende Zähne</b>. Die Weisheitszähne kommen oft erst später.</p><p>Bakterien im Zahnbelag wandeln Zucker in Säure um. Die Säure löst den Zahnschmelz auf: <b>Karies</b>. Deshalb sollte man zweimal täglich Zähne putzen.</p>',
  m: 'Zahnschmelz schützt den Zahn. Zucker, Bakterien und Säure verursachen Karies. Regelmäßiges Putzen und Zahnarztbesuche schützen.',
  aus: '<h3>Bau eines Zahns</h3><ul><li><b>Krone:</b> der sichtbare Teil mit dem harten Zahnschmelz.</li><li><b>Zahnbein:</b> weicher unter dem Schmelz.</li><li><b>Zahnmark:</b> Nerven und Blutgefäße im Inneren.</li><li><b>Wurzel:</b> im Kiefer verankert.</li></ul><h3>Zahnarten</h3><table><tr><th>Zahn</th><th>Aufgabe</th></tr><tr><td>Schneidezähne</td><td>abbeißen</td></tr><tr><td>Eckzähne</td><td>festhalten, reißen</td></tr><tr><td>Backenzähne</td><td>zermahlen</td></tr></table><h3>Karies</h3><p>Zahnbelag + Zucker → Säure → Loch im Schmelz. Wird nichts getan, erreicht es das Zahnmark und tut weh.</p><h3>Zahnpflege</h3><ul><li>Zweimal täglich drei Minuten putzen.</li><li>Zahnpasta mit Fluorid macht den Schmelz widerstandsfähig.</li><li>Zahnseide für die Zwischenräume.</li><li>Süßes und süße Getränke einschränken.</li><li>Zweimal im Jahr zum Zahnarzt.</li></ul>',
  f: [['🦷', 'Bau', 'Krone mit Schmelz, Zahnbein, Zahnmark und Wurzel.'], ['🍬', 'Karies', 'Bakterien machen aus Zucker Säure, die den Schmelz zerstört.'], ['🪥', 'Pflege', 'Zweimal täglich putzen, Zahnarzt, wenig Zucker.']],
  u: [['Wie viele Milchzähne hat ein Kind?', '20', '32', '28', '12', 'Das Milchgebiss hat 20 Zähne.'], ['Was verursacht Karies?', 'Säure aus Bakterien und Zucker', 'Zu viel Wasser', 'Zu viel Milch', 'Kaltes Wetter', 'Die Säure löst den Schmelz.'], ['Welcher Teil schützt den Zahn außen?', 'Der Zahnschmelz', 'Das Zahnmark', 'Die Wurzel', 'Das Zahnbein', 'Er ist das härteste Material im Körper.'], ['Wie oft sollte man Zähne putzen?', 'Mindestens zweimal täglich', 'Einmal pro Woche', 'Nur nach Süßem', 'Nie', 'Morgens und abends.']] });

kap('bio7-12', { e: '🩸❤️🧬', titel: 'Das Blut', bt: 'Blut transportiert, schützt und verschließt Wunden.',
  ein: '<p>Das Blut fließt durch den ganzen Körper. Es bringt <b>Sauerstoff und Nährstoffe</b> zu den Zellen und holt <b>Abfallstoffe</b> ab. Es enthält rote Blutzellen, weiße Blutzellen, Blutplättchen und Blutplasma.</p><p>Ein Erwachsener hat etwa 5 bis 6 Liter Blut.</p>',
  m: 'Blut transportiert, wehrt Krankheitserreger ab und verschließt Wunden.',
  aus: '<h3>Bestandteile</h3><table><tr><th>Bestandteil</th><th>Aufgabe</th></tr><tr><td>Blutplasma (flüssig, etwa 55 %)</td><td>Transport von Nährstoffen, Hormonen, Wärme</td></tr><tr><td>Rote Blutzellen</td><td>transportieren Sauerstoff (mit dem roten Farbstoff Hämoglobin)</td></tr><tr><td>Weiße Blutzellen</td><td>Abwehr von Krankheitserregern</td></tr><tr><td>Blutplättchen</td><td>Blutgerinnung</td></tr></table><h3>Wundverschluss</h3><p>Bei einer Verletzung verkleben Blutplättchen und bilden mit Fasern einen Pfropf. Es entsteht Schorf.</p><h3>Blutgruppen</h3><p>Es gibt die Blutgruppen A, B, AB und 0. Bei einer Bluttransfusion muss die Blutgruppe passen.</p><h3>Blutspende</h3><p>Blutspenden retten Leben. Man darf ab 18 Jahren spenden.</p>',
  f: [['🔴', 'Rote Zellen', 'Sie bringen Sauerstoff durch den Körper.'], ['⚪', 'Weiße Zellen', 'Sie bekämpfen Krankheitserreger.'], ['🩹', 'Plättchen', 'Sie verschließen Wunden.']],
  u: [['Was transportieren rote Blutzellen?', 'Sauerstoff', 'Abwehrstoffe', 'Hormone', 'Fett', 'Das übernimmt das Hämoglobin.'], ['Wofür sind weiße Blutzellen da?', 'Zur Abwehr von Erregern', 'Zum Transport von Sauerstoff', 'Zum Verschließen von Wunden', 'Für den Geschmack', 'Sie sind Teil des Immunsystems.'], ['Was verschließt eine Wunde?', 'Blutplättchen', 'Rote Blutzellen', 'Blutplasma', 'Weiße Blutzellen', 'Sie bilden einen Gerinnungspfropf.'], ['Wie viel Blut hat ein Erwachsener etwa?', '5 bis 6 Liter', '1 Liter', '20 Liter', '50 Liter', 'Das ist etwa ein Dreizehntel des Körpergewichts.']] });

kap('bio7-13', { e: '🚑🩹📞', titel: 'Erste Hilfe', bt: 'Ruhig bleiben, absichern, Notruf 112.',
  ein: '<p>Wenn jemand verletzt ist, kann jeder helfen. Wichtig ist: <b>Ruhe bewahren</b>, dich selbst nicht in Gefahr bringen und den <b>Notruf 112</b> wählen. Der Anruf ist kostenlos.</p><p>Bleibe beim Verletzten und tröste ihn, bis Hilfe kommt.</p>',
  m: 'Erste Hilfe: Eigenschutz, Absichern, Notruf 112, Helfen. Bei Bewusstlosigkeit mit Atmung: stabile Seitenlage.',
  aus: '<h3>Die Reihenfolge</h3><ol><li><b>Selbst schützen:</b> Warnweste, Gefahrenstelle sichern.</li><li><b>Notruf 112:</b> Wo ist es? Was ist passiert? Wie viele Verletzte? Welche Verletzungen? Warten auf Rückfragen.</li><li><b>Helfen:</b> Verletzten ansprechen, trösten, Wunden versorgen.</li></ol><h3>Wunden</h3><p>Bei Blutungen ein sauberes Tuch auf die Wunde drücken, Verband anlegen, Arm oder Bein hochhalten.</p><h3>Verbrennungen</h3><p>Etwa zehn Minuten mit kühlem (nicht eiskaltem) Wasser kühlen. Nichts auf die Wunde streichen.</p><h3>Bewusstlos, aber atmet</h3><p>In die <b>stabile Seitenlage</b> bringen, damit die Atemwege frei bleiben und nichts in die Lunge gerät.</p><h3>Atmet nicht</h3><p>112 anrufen und fest in der Mitte der Brust drücken (100 bis 120 Mal pro Minute). Wenn ein Defibrillator da ist, dessen Anweisungen folgen.</p><p><b>Falsche Hilfe gibt es kaum. Nichts tun ist der größte Fehler.</b></p>',
  f: [['📞', '112', 'Die Notrufnummer ist kostenlos und gilt in ganz Europa.'], ['🩹', 'Wunden', 'Sauber abdecken, bei Blutung Druck ausüben.'], ['🛌', 'Seitenlage', 'Bewusstlose, die atmen, kommen in die stabile Seitenlage.']],
  u: [['Welche Nummer wählt man im Notfall?', '112', '110', '116', '0800', '112 erreicht Rettungsdienst und Feuerwehr.'], ['Was kommt bei Verbrennungen auf die Wunde?', 'Kühles Wasser', 'Butter', 'Mehl', 'Eis direkt', 'Mit kühlem Wasser etwa zehn Minuten kühlen.'], ['Was macht man bei Bewusstlosigkeit mit Atmung?', 'Stabile Seitenlage', 'Hinsetzen', 'Trinken geben', 'Aufstehen lassen', 'So bleiben die Atemwege frei.'], ['Was ist der größte Fehler?', 'Nichts tun', 'Den Notruf wählen', 'Den Verletzten trösten', 'Die Wunde abdecken', 'Jede Hilfe ist besser als keine.']] });

kap('bio7-14', { e: '👁️🔍🌈', titel: 'Das Auge', bt: 'Die Netzhaut fängt das Bild ein.',
  ein: '<p>Licht fällt durch die <b>Pupille</b> ins Auge. Die <b>Linse</b> bündelt es und erzeugt auf der <b>Netzhaut</b> ein kleines, auf dem Kopf stehendes Bild. Der <b>Sehnerv</b> leitet es zum Gehirn, das es wieder umdreht.</p><p>Bei hellem Licht wird die Pupille klein, im Dunkeln groß.</p>',
  m: 'Hornhaut, Pupille und Linse lenken das Licht auf die Netzhaut. Sehzellen wandeln es in Signale um.',
  aus: '<h3>Bauteile</h3><table><tr><th>Teil</th><th>Aufgabe</th></tr><tr><td>Hornhaut</td><td>durchsichtiger Schutz vorne, bricht das Licht</td></tr><tr><td>Iris (Regenbogenhaut)</td><td>Muskel, der die Pupille einstellt, gibt dem Auge die Farbe</td></tr><tr><td>Pupille</td><td>Loch, durch das Licht eintritt</td></tr><tr><td>Linse</td><td>stellt scharf</td></tr><tr><td>Glaskörper</td><td>füllt das Auge</td></tr><tr><td>Netzhaut</td><td>enthält Sehzellen</td></tr><tr><td>Sehnerv</td><td>leitet Signale ins Gehirn</td></tr></table><h3>Sehzellen</h3><p><b>Zapfen</b> sehen Farben bei Licht, <b>Stäbchen</b> sehen Hell und Dunkel bei wenig Licht.</p><h3>Sehfehler</h3><ul><li>Kurzsichtigkeit: Das Auge ist zu lang, ferne Dinge sind unscharf (Brille mit Zerstreuungslinse).</li><li>Weitsichtigkeit: nahe Dinge sind unscharf (Sammellinse).</li></ul><h3>Schutz</h3><p>Wimpern, Lider und Tränen schützen das Auge. Nie direkt in die Sonne schauen.</p>',
  f: [['⚫', 'Pupille', 'Sie regelt, wie viel Licht ins Auge kommt.'], ['🔍', 'Linse', 'Sie bündelt das Licht auf der Netzhaut.'], ['🎨', 'Zapfen', 'Sie sehen Farben, Stäbchen sehen im Dunkeln.']],
  u: [['Wo entsteht das Bild im Auge?', 'Auf der Netzhaut', 'Auf der Hornhaut', 'In der Pupille', 'Im Glaskörper', 'Dort liegen die Sehzellen.'], ['Welche Sehzellen sehen Farben?', 'Zapfen', 'Stäbchen', 'Nervenzellen', 'Hautzellen', 'Zapfen arbeiten bei Licht.'], ['Was passiert mit der Pupille bei hellem Licht?', 'Sie wird klein', 'Sie wird groß', 'Sie wird bunt', 'Sie bleibt gleich', 'Das schützt die Netzhaut.'], ['Was hilft bei Kurzsichtigkeit?', 'Eine Brille mit Zerstreuungslinse', 'Eine Sammellinse', 'Dunkle Brille', 'Mehr Karotten', 'Sie bringt das Bild auf die Netzhaut.']] });

kap('bio7-15', { e: '👂🎵🔊', titel: 'Das Ohr und Hören', bt: 'Schallwellen werden zu Nervensignalen.',
  ein: '<p>Die <b>Ohrmuschel</b> fängt Schall auf. Er läuft durch den Gehörgang zum <b>Trommelfell</b> und bringt es zum Schwingen. Drei kleine Knochen im Mittelohr (<b>Hammer, Amboss, Steigbügel</b>) geben die Schwingung weiter. In der <b>Schnecke</b> im Innenohr entstehen Nervensignale.</p>',
  m: 'Außenohr fängt Schall, Mittelohr verstärkt, Innenohr wandelt in Nervensignale um.',
  aus: '<h3>Die drei Teile</h3><ul><li><b>Außenohr:</b> Ohrmuschel, Gehörgang, Trommelfell.</li><li><b>Mittelohr:</b> Hammer, Amboss, Steigbügel. Die Ohrtrompete gleicht den Druck aus (deshalb knackt es im Flugzeug).</li><li><b>Innenohr:</b> Hörschnecke mit Haarsinneszellen, außerdem das Gleichgewichtsorgan.</li></ul><h3>Gleichgewicht</h3><p>In den drei Bogengängen bewegt sich Flüssigkeit und meldet dem Gehirn Drehungen des Kopfes.</p><h3>Lärm</h3><p>Zu laute Geräusche zerstören die Haarsinneszellen für immer. Ab etwa 85 Dezibel ist das Risiko hoch, bei Kopfhörern daher Lautstärke begrenzen.</p><h3>Schutz</h3><p>Gehörschutz bei Konzerten, Pausen vom Lärm und keine Wattestäbchen im Gehörgang.</p>',
  f: [['👂', 'Außenohr', 'Ohrmuschel und Gehörgang leiten den Schall zum Trommelfell.'], ['🦴', 'Mittelohr', 'Hammer, Amboss und Steigbügel verstärken die Schwingung.'], ['🐌', 'Innenohr', 'In der Schnecke entstehen die Nervensignale.']],
  u: [['Welche Knochen liegen im Mittelohr?', 'Hammer, Amboss, Steigbügel', 'Speiche, Elle, Schienbein', 'Wirbel', 'Rippen', 'Sie sind die kleinsten Knochen im Körper.'], ['Wo entstehen die Nervensignale beim Hören?', 'In der Hörschnecke', 'Im Trommelfell', 'In der Ohrmuschel', 'Im Gehörgang', 'Haarsinneszellen wandeln Schall um.'], ['Was kann bei Lärm passieren?', 'Haarsinneszellen sterben ab', 'Das Trommelfell wächst', 'Man hört besser', 'Nichts', 'Der Schaden bleibt dauerhaft.'], ['Wofür sind die Bogengänge?', 'Fürs Gleichgewicht', 'Fürs Hören hoher Töne', 'Für den Geruch', 'Für den Druck', 'Sie melden Drehungen des Kopfes.']] });

kap('bio7-16', { e: '🖐️🌡️🥶', titel: 'Die Haut als Sinnesorgan', bt: 'Die Haut ist unser größtes Organ.',
  ein: '<p>Die <b>Haut</b> schützt den Körper, hält Wasser im Körper und regelt die Temperatur. In der Haut sitzen viele Sinneszellen für <b>Berührung, Druck, Wärme, Kälte und Schmerz</b>.</p><p>Die Fingerspitzen haben besonders viele Tastsinneszellen.</p>',
  m: 'Die Haut schützt, fühlt und reguliert die Temperatur. Sonnenschutz ist wichtig.',
  aus: '<h3>Die Schichten</h3><ul><li><b>Oberhaut:</b> äußerste Schutzschicht, ständig erneuert, enthält Pigmente für die Hautfarbe.</li><li><b>Lederhaut:</b> Nerven, Blutgefäße, Schweißdrüsen, Haarwurzeln.</li><li><b>Unterhaut:</b> Fettgewebe, Wärmeschutz und Polster.</li></ul><h3>Sinneszellen</h3><p>Es gibt Rezeptoren für Berührung, Druck, Wärme, Kälte und Schmerz. Schmerz warnt vor Gefahr.</p><h3>Temperaturregelung</h3><p>Bei Hitze schwitzt man, die Verdunstung kühlt. Bei Kälte ziehen sich Blutgefäße zusammen, man bekommt Gänsehaut.</p><h3>Schutz und Pflege</h3><ul><li>Sonnencreme und Kleidung gegen Sonnenbrand und Hautkrebs.</li><li>Wunden sauber halten.</li><li>Viel trinken, damit die Haut nicht austrocknet.</li></ul>',
  f: [['🧱', 'Schichten', 'Oberhaut, Lederhaut und Unterhaut.'], ['🤚', 'Tastsinn', 'Rezeptoren melden Berührung, Druck, Wärme, Kälte und Schmerz.'], ['☀️', 'Schutz', 'Sonnencreme schützt vor Sonnenbrand.']],
  u: [['Welche Schicht ist die äußerste?', 'Die Oberhaut', 'Die Lederhaut', 'Die Unterhaut', 'Das Fettgewebe', 'Sie schützt vor Wasserverlust.'], ['Was spürt die Haut?', 'Druck, Wärme, Kälte, Schmerz', 'Nur Wärme', 'Nur Licht', 'Nur Geräusche', 'Dafür gibt es verschiedene Rezeptoren.'], ['Wie kühlt sich der Körper bei Hitze?', 'Durch Schwitzen', 'Durch Gänsehaut', 'Durch Zittern', 'Durch Frieren', 'Die Verdunstung nimmt Wärme mit.'], ['Wozu dient Sonnencreme?', 'Schutz vor UV-Strahlung', 'Zum Schwitzen', 'Zum Kühlen', 'Für den Duft', 'UV-Strahlung schädigt die Haut.']] });

kap('bio7-17', { e: '🐕🦅🦇', titel: 'Sinne im Tierreich', bt: 'Tiere haben Sinne, die wir nicht haben.',
  ein: '<p>Viele Tiere nehmen die Welt ganz anders wahr als wir. <b>Hunde</b> riechen viel besser, <b>Adler</b> sehen viel schärfer, <b>Fledermäuse</b> hören Ultraschall, <b>Bienen</b> sehen UV-Licht und manche <b>Schlangen</b> spüren Wärme.</p>',
  m: 'Jede Tierart hat Sinne, die zu ihrer Lebensweise passen.',
  aus: '<h3>Beispiele</h3><table><tr><th>Tier</th><th>Besonderer Sinn</th></tr><tr><td>Hund</td><td>Geruch: etwa 200 Millionen Riechzellen (Mensch etwa 5 Millionen)</td></tr><tr><td>Adler</td><td>Sehen: erkennt Beute aus mehreren hundert Metern</td></tr><tr><td>Fledermaus</td><td>Hören: Ultraschall-Echoortung</td></tr><tr><td>Biene</td><td>sieht UV-Licht, das Blüten Muster zeigt</td></tr><tr><td>Klapperschlange</td><td>Grubenorgane spüren Wärmestrahlung</td></tr><tr><td>Hai</td><td>spürt elektrische Felder von Beutetieren</td></tr><tr><td>Katze</td><td>Nachtsicht und Tasthaare</td></tr></table><h3>Warum so verschieden?</h3><p>Sinne entwickeln sich passend zum Lebensraum: Nachtjäger hören und tasten gut, Tagjäger sehen scharf, Tiere im Meer nutzen elektrische oder chemische Reize.</p><h3>Wir und die Tiere</h3><p>Menschen nutzen Hunde als Spürhunde und Blindenführhunde, weil sie so gut riechen und lernen.</p>',
  f: [['👃', 'Riechen', 'Hunde riechen viele Male besser als wir.'], ['🔊', 'Hören', 'Fledermäuse nutzen Ultraschall.'], ['🌈', 'Sehen', 'Bienen sehen UV-Licht, Adler sehr scharf.']],
  u: [['Welches Tier riecht besonders gut?', 'Der Hund', 'Der Adler', 'Die Biene', 'Der Fisch', 'Er hat sehr viele Riechzellen.'], ['Welches Tier orientiert sich mit Ultraschall?', 'Die Fledermaus', 'Die Taube', 'Der Frosch', 'Der Igel', 'Das Echo zeigt ihr den Weg.'], ['Was sehen Bienen, was wir nicht sehen?', 'UV-Licht', 'Infrarot', 'Röntgenstrahlen', 'Radiowellen', 'Blütenmuster zeigen den Weg zum Nektar.'], ['Warum haben Tiere unterschiedliche Sinne?', 'Sie passen zur Lebensweise', 'Zufall allein', 'Sie lernen sie', 'Sie bekommen sie vom Menschen', 'Die Evolution hat sie angepasst.']] });

kap('bio7-18', { e: '🌸📅🩸', titel: 'Der Zyklus und die Menstruation', bt: 'Der Körper bereitet sich jeden Monat auf eine Schwangerschaft vor.',
  ein: '<p>In der Pubertät beginnt bei Mädchen der <b>Zyklus</b>. Etwa alle vier Wochen reift in einem Eierstock eine <b>Eizelle</b> heran. Die Gebärmutterschleimhaut baut sich auf, damit sich eine befruchtete Eizelle einnisten könnte.</p><p>Wird die Eizelle nicht befruchtet, löst sich die Schleimhaut und wird mit etwas Blut ausgeschieden: die <b>Menstruation</b> (Periode, Regelblutung).</p>',
  m: 'Der Zyklus dauert meist 21 bis 35 Tage. Die Menstruation ist normal und gesund.',
  aus: '<h3>Die Phasen</h3><ol><li><b>Menstruation:</b> Tag 1 bis etwa 5, Blutung.</li><li><b>Aufbauphase:</b> eine Eizelle reift, die Schleimhaut wächst.</li><li><b>Eisprung:</b> etwa in der Mitte des Zyklus springt die Eizelle in den Eileiter.</li><li><b>Gelbkörperphase:</b> Schleimhaut bleibt bereit. Ohne Befruchtung folgt wieder die Blutung.</li></ol><h3>Hormone</h3><p>Östrogen und Progesteron steuern den Zyklus.</p><h3>Wann beginnt es?</h3><p>Meist zwischen 10 und 15 Jahren. Am Anfang ist der Zyklus oft unregelmäßig. Jedes Mädchen entwickelt sich in seinem eigenen Tempo.</p><h3>Hygiene und Alltag</h3><ul><li>Binden, Tampons oder Menstruationstassen verwenden und regelmäßig wechseln.</li><li>Sport, Duschen und Schule sind normal möglich.</li><li>Bei starken Schmerzen oder sehr langen Blutungen: Ärztin fragen.</li></ul><h3>Für alle</h3><p>Die Periode ist kein Grund zur Scham. Auch Jungen sollten sie verstehen, damit sie respektvoll sind.</p>',
  f: [['🥚', 'Eisprung', 'Etwa in der Mitte des Zyklus verlässt eine Eizelle den Eierstock.'], ['🩸', 'Menstruation', 'Die Gebärmutterschleimhaut wird ausgeschieden, wenn keine Befruchtung stattfindet.'], ['🧴', 'Hygiene', 'Binden, Tampons oder Tassen regelmäßig wechseln.']],
  u: [['Wie lange dauert ein Zyklus meist?', 'Etwa 28 Tage (21 bis 35)', '7 Tage', '60 Tage', '3 Tage', 'Er ist von Mädchen zu Mädchen verschieden.'], ['Was passiert beim Eisprung?', 'Die Eizelle verlässt den Eierstock', 'Die Blutung beginnt', 'Die Gebärmutter wird größer', 'Ein Baby wird geboren', 'Sie wandert in den Eileiter.'], ['Was ist die Menstruation?', 'Das Ausscheiden der Gebärmutterschleimhaut', 'Eine Krankheit', 'Eine Schwangerschaft', 'Ein Hormon', 'Sie ist normal und gesund.'], ['Wann beginnt die Periode meist?', 'Zwischen 10 und 15 Jahren', 'Mit 5 Jahren', 'Mit 25 Jahren', 'Mit 40 Jahren', 'Jedes Mädchen hat sein eigenes Tempo.']] });
